export async function sync({ dir, client, stateDir, log = () => {}, warn = () => {}, signal }) {
  const failures = new Failures();
  const unreadableDirs = [];
  const files = await listFiles(dir, {
    onSkip: (relPath, reason) => warn(`skipping ${relPath}: ${reason}`),
