req.on('socket', (socket) => {
  if (!socket.pending) {
    // Kept alive from an earlier request.
    onConnect();
  } else if (socket.connecting) {
    socket.once('connect', onConnect);
  }
  // Otherwise connecting has failed already, and the error is on its way.
});

